    {"offset": {"line": 78, "column": 0}, "map": {"version":3,"sources":["file:///C:/myProject/Intellibus/Intellicare/intellicare_demo1/components/header.tsx"],"sourcesContent":["\"use client\"\n\nimport Link from \"next/link\"\nimport { Button } from \"@/components/ui/button\"\nimport { useState, useEffect } from \"react\"\nimport { usePathname } from \"next/navigation\"\nimport Image from \"next/image\"\nimport { Menu, X } from \"lucide-react\"\n\n/**\n * Main navigation header component\n * Shows admin login button or admin panel access based on authentication status\n */\nexport default function Header() {\n  const [isAdminLoggedIn, setIsAdminLoggedIn] = useState(false)\n  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)\n  const pathname = usePathname()\n\n  // Check admin authentication status on mount and when pathname changes\n  useEffect(() => {\n    const adminSession = localStorage.getItem(\"admin_session\")\n    setIsAdminLoggedIn(adminSession === \"true\")\n  }, [pathname])\n\n  useEffect(() => {\n    setIsMobileMenuOpen(false)\n  }, [pathname])\n\n  const isActive = (href: string) => pathname === href\n\n  return (\n    <header className=\"sticky top-0 z-50 border-b border-border bg-card/95 backdrop-blur-sm\">\n      <div className=\"max-w-6xl mx-auto px-4 py-4 flex items-center justify-between\">\n        {/* Logo */}\n        <Link\n          href=\"/\"\n          className=\"flex items-center gap-3 font-bold text-xl hover:opacity-80 transition\"\n        >\n          <Image\n            src=\"/images/image.png\"\n            alt=\"Intellibus\"\n            width={32}\n            height={32}\n            className=\"h-8 w-auto\"\n          />\n          <span className=\"hidden sm:inline text-foreground\">\n            Intellibus Care\n          </span>\n        </Link>\n\n        {/* Navigation */}\n        <nav className=\"hidden md:flex items-center gap-8\">\n          <Link\n            href=\"/about\"\n            aria-current={isActive(\"/doctors\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/doctors\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            About\n          </Link>\n\n          <Link\n            href=\"/what-we-do\"\n            aria-current={isActive(\"/doctors\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/doctors\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            What we Do\n          </Link>\n          \n          <Link\n            href=\"/doctors\"\n            aria-current={isActive(\"/doctors\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/doctors\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            Doctors\n          </Link>\n          <Link\n            href=\"/missions\"\n            aria-current={isActive(\"/missions\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/missions\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            Missions\n          </Link>\n\n          <Link\n            href=\"/media\"\n            aria-current={isActive(\"/doctors\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/doctors\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            Media\n          </Link>\n\n          <Link\n            href=\"/register\"\n            aria-current={isActive(\"/register\") ? \"page\" : undefined}\n            className={`transition-colors ${\n              isActive(\"/register\")\n                ? \"text-primary font-semibold border-b-2 border-primary\"\n                : \"text-foreground hover:text-primary\"\n            }`}\n          >\n            Register\n          </Link>\n        </nav>\n\n        {/* CTA Buttons */}\n        <div className=\"flex items-center gap-2\">\n          <Link href=\"/register\" className=\"hidden md:block\">\n            <Button className=\"bg-primary text-primary-foreground hover:bg-primary/90\">\n              Get Started\n            </Button>\n          </Link>\n\n          <button\n            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}\n            className=\"md:hidden p-2 hover:bg-muted rounded-lg transition-colors\"\n            aria-label={isMobileMenuOpen ? \"Close menu\" : \"Open menu\"}\n            aria-expanded={isMobileMenuOpen}\n          >\n            {isMobileMenuOpen ? (\n              <X className=\"h-6 w-6\" />\n            ) : (\n              <Menu className=\"h-6 w-6\" />\n            )}\n          </button>\n        </div>\n      </div>\n\n      {isMobileMenuOpen && (\n        <div className=\"md:hidden border-t border-border bg-card\">\n          <nav className=\"max-w-6xl mx-auto px-4 py-6 flex flex-col gap-4\">\n            <Link\n              href=\"/\"\n              className={`px-4 py-3 rounded-lg transition-colors ${\n                isActive(\"/\")\n                  ? \"bg-primary text-primary-foreground font-semibold\"\n                  : \"hover:bg-muted\"\n              }`}\n            >\n              Home\n            </Link>\n            <Link\n              href=\"/doctors\"\n              className={`px-4 py-3 rounded-lg transition-colors ${\n                isActive(\"/doctors\")\n                  ? \"bg-primary text-primary-foreground font-semibold\"\n                  : \"hover:bg-muted\"\n              }`}\n            >\n              Doctors\n            </Link>\n            <Link\n              href=\"/missions\"\n              className={`px-4 py-3 rounded-lg transition-colors ${\n                isActive(\"/missions\")\n                  ? \"bg-primary text-primary-foreground font-semibold\"\n                  : \"hover:bg-muted\"\n              }`}\n            >\n              Missions\n            </Link>\n            <Link\n              href=\"/register\"\n              className={`px-4 py-3 rounded-lg transition-colors ${\n                isActive(\"/register\")\n                  ? \"bg-primary text-primary-foreground font-semibold\"\n                  : \"hover:bg-muted\"\n              }`}\n            >\n              Register\n            </Link>\n            <Link href=\"/register\" className=\"mt-2\">\n              <Button className=\"w-full bg-primary text-primary-foreground hover:bg-primary/90\">\n                Get Started\n              </Button>\n            </Link>\n          </nav>\n        </div>\n      )}\n    </header>\n  );\n}\n"],"names":[],"mappings":";;;;;AAEA;AACA;AACA;AACA;AACA;AACA;AAAA;AAPA;;;;;;;;AAae,SAAS;IACtB,MAAM,CAAC,iBAAiB,mBAAmB,GAAG,IAAA,iNAAQ,EAAC;IACvD,MAAM,CAAC,kBAAkB,oBAAoB,GAAG,IAAA,iNAAQ,EAAC;IACzD,MAAM,WAAW,IAAA,iJAAW;IAE5B,uEAAuE;IACvE,IAAA,kNAAS,EAAC;QACR,MAAM,eAAe,aAAa,OAAO,CAAC;QAC1C,mBAAmB,iBAAiB;IACtC,GAAG;QAAC;KAAS;IAEb,IAAA,kNAAS,EAAC;QACR,oBAAoB;IACtB,GAAG;QAAC;KAAS;IAEb,MAAM,WAAW,CAAC,OAAiB,aAAa;IAEhD,qBACE,8OAAC;QAAO,WAAU;;0BAChB,8OAAC;gBAAI,WAAU;;kCAEb,8OAAC,uKAAI;wBACH,MAAK;wBACL,WAAU;;0CAEV,8OAAC,wIAAK;gCACJ,KAAI;gCACJ,KAAI;gCACJ,OAAO;gCACP,QAAQ;gCACR,WAAU;;;;;;0CAEZ,8OAAC;gCAAK,WAAU;0CAAmC;;;;;;;;;;;;kCAMrD,8OAAC;wBAAI,WAAU;;0CACb,8OAAC,uKAAI;gCACH,MAAK;gCACL,gBAAc,SAAS,cAAc,SAAS;gCAC9C,WAAW,CAAC,kBAAkB,EAC5B,SAAS,cACL,yDACA,sCACJ;0CACH;;;;;;0CAID,8OAAC,uKAAI;gCACH,MAAK;gCACL,gBAAc,SAAS,cAAc,SAAS;gCAC9C,WAAW,CAAC,kBAAkB,EAC5B,SAAS,cAC